/** Exercises composed frames, real long presses and layout stability on the project emulator. */
final class PlayerToolsChecks {
    final Instrumentation test;final MainActivity a;int checks;
    PlayerToolsChecks(Instrumentation test,MainActivity a){this.test=test;this.a=a;}
    interface Condition{boolean ok()throws Exception;}
    void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);Diag.log("PLAYER TOOLS TEST",message);}
    void waitFor(Condition condition,int timeout)throws Exception{long end=SystemClock.elapsedRealtime()+timeout;while(SystemClock.elapsedRealtime()<end){if(condition.ok())return;Thread.sleep(60);}throw new AssertionError("Timed out waiting for player tools");}
    void main(Runnable action){test.runOnMainSync(action);}
    Object field(Object value,String name)throws Exception{Field f=value.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(value);}
    View content(Activity activity){return activity.findViewById(android.R.id.content);}
    <T extends View>T find(View view,Class<T> type){if(type.isInstance(view)&&view.getVisibility()==View.VISIBLE)return type.cast(view);if(view instanceof ViewGroup group)for(int i=0;i<group.getChildCount();i++){T found=find(group.getChildAt(i),type);if(found!=null)return found;}return null;}
    Button button(View view,String label){if(view instanceof Button b&&label.equals(b.getText().toString()))return b;if(view instanceof ViewGroup group)for(int i=0;i<group.getChildCount();i++){Button found=button(group.getChildAt(i),label);if(found!=null)return found;}return null;}
    boolean textContains(View view,String term){if(view instanceof TextView text&&text.getText().toString().contains(term))return true;if(view instanceof ViewGroup group)for(int i=0;i<group.getChildCount();i++)if(textContains(group.getChildAt(i),term))return true;return false;}
    void fixture(String mode)throws Exception{try(InputStream in=new URL("http://10.0.2.2:8080/test/"+mode).openStream()){while(in.read()!=-1){}}}
    long stamp(TextureView output){return output.getSurfaceTexture().getTimestamp();}
    Rect bounds(View view){int[] xy=new int[2];view.getLocationOnScreen(xy);return new Rect(xy[0],xy[1],xy[0]+view.getWidth(),xy[1]+view.getHeight());}
    void show(View view)throws Exception{main(()->view.requestRectangleOnScreen(new Rect(0,0,view.getWidth(),view.getHeight()),true));test.waitForIdleSync();Thread.sleep(150);}
    long down(View view)throws Exception{show(view);Rect r=new Rect();check(view.getGlobalVisibleRect(r)&&r.height()>=view.getHeight()-2,"Held frame button has a full visible touch target");r=bounds(view);long at=SystemClock.uptimeMillis();MotionEvent event=MotionEvent.obtain(at,at,MotionEvent.ACTION_DOWN,r.centerX(),r.centerY(),0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);test.getUiAutomation().injectInputEvent(event,true);event.recycle();return at;}
    void release(View view,long down,int action){Rect r=bounds(view);MotionEvent event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,r.centerX(),r.centerY(),0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);test.getUiAutomation().injectInputEvent(event,true);event.recycle();}
    void shot(String name)throws Exception{test.waitForIdleSync();Thread.sleep(200);File dir=new File(a.getExternalFilesDir(null),"player-tools-audit");dir.mkdirs();Bitmap bitmap=test.getUiAutomation().takeScreenshot();try(OutputStream out=new FileOutputStream(new File(dir,name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
    String run()throws Exception{
        if(!Set.of("ranchu","goldfish").contains(Build.HARDWARE))throw new AssertionError("Project emulator required");
        StorageLocation.reset(a);fixture("card/1");RoadApp.instance.session.get("SD_STATUS");fixture("list/multi");a.getSharedPreferences("playback",0).edit().putBoolean("software",true).commit();
        File file=new File(a.getCacheDir(),"frame-tools.mp4");try(InputStream in=new URL("http://10.0.2.2:8080/storage/fullhd-aac.mp4").openStream();OutputStream out=new FileOutputStream(file)){Io.copy(in,out);}Uri source=Library.publish(a,file,"Frame-tools.mp4","video/mp4","Tests");Library.add(a,source,"Frame-tools.mp4","video/mp4",file.length(),"test original");file.delete();
        PlayerActivity activity=(PlayerActivity)test.startActivitySync(PlaybackQueue.local(a,Library.all(a),source.toString()).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
        waitFor(()->Boolean.TRUE.equals(field(activity,"haveVideoFrame")),16000);org.videolan.libvlc.MediaPlayer player=(org.videolan.libvlc.MediaPlayer)field(activity,"player");TextureView output=find((View)field(activity,"video"),TextureView.class);
        main(()->{if(player.isPlaying())player.pause();});waitFor(()->!player.isPlaying(),3000);Thread.sleep(200);long seekStamp=stamp(output);main(()->player.setTime(5000,false));waitFor(()->Math.abs(player.getTime()-5000)<80&&stamp(output)!=seekStamp,7000);Thread.sleep(250);
        Button forward=button(content(activity),"Кадр вперёд"),back=button(content(activity),"Кадр назад");check(forward!=null&&back!=null,"Both frame directions are visible actions");show(forward);
        View video=(View)field(activity,"video"),controls=(View)field(activity,"controlScroll");Rect beforeVideo=bounds(video),beforeControls=bounds(controls);int[] jumps={0};ViewTreeObserver.OnGlobalLayoutListener listener=()->{if(!beforeVideo.equals(bounds(video))||!beforeControls.equals(bounds(controls)))jumps[0]++;};main(()->content(activity).getViewTreeObserver().addOnGlobalLayoutListener(listener));
        Bitmap before=output.getBitmap();long at=player.getTime();main(forward::performClick);waitFor(()->field(activity,"pausedFrame")!=null&&(Long)field(activity,"framePosition")>at,10000);long ahead=(Long)field(activity,"framePosition");check(ahead-at<=100&&!player.isPlaying(),"Forward advances one source-frame interval while paused");Bitmap advanced=((Bitmap)field(activity,"pausedFrame")).copy(Bitmap.Config.ARGB_8888,false);check(!before.sameAs(advanced),"Forward decodes a different actual source frame");before.recycle();
        main(back::performClick);waitFor(()->!(Boolean)field(activity,"frameSeekPending")&&(Long)field(activity,"framePosition")<ahead,7000);long behind=(Long)field(activity,"framePosition");Bitmap earlier=((Bitmap)field(activity,"pausedFrame")).copy(Bitmap.Config.ARGB_8888,false);check(ahead-behind<=100&&!earlier.sameAs(advanced)&&!player.isPlaying(),"Back presents the actual earlier frame while paused");
        main(forward::performClick);waitFor(()->!(Boolean)field(activity,"frameSeekPending")&&(Long)field(activity,"framePosition")==ahead,7000);check(advanced.sameAs((Bitmap)field(activity,"pausedFrame")),"Forward after Back returns to the exact same decoded frame");advanced.recycle();earlier.recycle();
        TextView status=(TextView)field(activity,"status");String label=status.getText().toString();main(()->status.setText("Загрузка видео · 42%"));Thread.sleep(250);main(()->status.setText(label));Thread.sleep(250);check(beforeVideo.equals(bounds(video))&&beforeControls.equals(bounds(controls))&&jumps[0]==0,"Status changes and frame seeks preserve the video and controls bounds");
        long startPosition=(Long)field(activity,"framePosition"),pressed=down(forward);Thread.sleep(ViewConfiguration.getLongPressTimeout()+(Build.VERSION.SDK_INT<28?3500L:1450L));release(forward,pressed,MotionEvent.ACTION_UP);Thread.sleep(500);long stopped=(Long)field(activity,"framePosition");check(stopped-startPosition>=66&&stopped-startPosition<=700,"A real held press slowly presents multiple frames without large jumps: "+(stopped-startPosition)+"ms");Thread.sleep(650);check((Long)field(activity,"framePosition")==stopped&&!player.isPlaying(),"Releasing the button stops frame repetition without a trailing click");check(jumps[0]==0,"Holding the frame button never shifts the video viewport");
        long backAt=(Long)field(activity,"framePosition"),backPressed=down(back);Thread.sleep(ViewConfiguration.getLongPressTimeout()+(Build.VERSION.SDK_INT<28?2200L:800L));release(back,backPressed,MotionEvent.ACTION_CANCEL);Thread.sleep(450);long cancelled=(Long)field(activity,"framePosition");check(cancelled<backAt,"Holding Back also moves through earlier frames");Thread.sleep(600);check((Long)field(activity,"framePosition")==cancelled,"Cancelling a held gesture stops repeated seeking");
        long continuedFrom=(Long)field(activity,"framePosition"),nativeStamp=stamp(output);Button play=(Button)field(activity,"play");main(play::performClick);waitFor(()->player.isPlaying()&&player.getTime()>continuedFrom+200&&field(activity,"pausedFrame")==null&&stamp(output)!=nativeStamp,8000);check(true,"Normal moving video resumes from the chosen exact frame and removes the still overlay");main(play::performClick);
        main(()->{try{Method clear=PlayerActivity.class.getDeclaredMethod("clearFrame");clear.setAccessible(true);clear.invoke(activity);}catch(Exception e){throw new RuntimeException(e);}if(player.isPlaying())player.pause();player.setTime(0,false);});waitFor(()->player.getTime()==0,5000);Thread.sleep(350);main(back::performClick);Thread.sleep(300);check(player.getTime()==0&&!player.isPlaying(),"Back at the first frame stays at zero without starting playback");
        main(()->content(activity).getViewTreeObserver().removeOnGlobalLayoutListener(listener));shot("player");main(activity::finish);waitFor(activity::isDestroyed,5000);
        MediaItem remoteItem=new MediaItem(new JSONObject().put("f","/storage/fullhd-aac.mp4").put("t","20261104120000").put("d",60),0);PlayerActivity remote=(PlayerActivity)test.startActivitySync(PlaybackQueue.remote(a,RoadApp.instance.session,Collections.singletonList(remoteItem),remoteItem).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->Boolean.TRUE.equals(field(remote,"haveVideoFrame")),16000);Button remoteStep=button(content(remote),"Кадр вперёд");main(remoteStep::performClick);waitFor(()->field(remote,"pausedFrame")!=null,20000);check(((ImageView)field(remote,"frameImage")).getVisibility()==View.VISIBLE,"Exact frame stepping also renders a real frame through the Wi-Fi media relay");main(remote::finish);waitFor(remote::isDestroyed,5000);
        main(()->a.navigate(1));waitFor(()->!a.remoteLoading&&a.remote.size()==4,7000);checkSelection(a.fileList,button(content(a),"Выбрать"),"archive");
        main(()->a.navigate(2));waitFor(()->button(content(a),"Выбрать")!=null,4000);check(!textContains(content(a),"Добавить существующие файлы"),"The removed import button is absent from the phone library");checkSelection(a.localList,button(content(a),"Выбрать"),"phone");
        Intent folders=MediaOpen.folderChooser(a);Intent primary=folders.getParcelableExtra(Intent.EXTRA_INTENT);android.os.Parcelable[] options=folders.getParcelableArrayExtra(Intent.EXTRA_INITIAL_INTENTS);boolean downloads=false,directory=false;for(android.os.Parcelable option:options){Intent intent=(Intent)option;downloads|=android.app.DownloadManager.ACTION_VIEW_DOWNLOADS.equals(intent.getAction());directory|="vnd.android.document/directory".equals(intent.getType());}check("resource/folder".equals(primary.getType())&&downloads&&directory,"Folder chooser retains MiXplorer and document intents and includes the system Downloads action");
        main(a::showAbout);test.waitForIdleSync();AlertDialog about=a.aboutDialog;Button update=button(about.getWindow().getDecorView(),"Проверить обновления");check(update!=null&&update.isSelected(),"About uses an accent-filled primary update button");check(button(about.getWindow().getDecorView(),"Репозиторий")!=null&&button(about.getWindow().getDecorView(),"Лицензии")!=null,"About keeps separate repository and license actions");show(update);shot("about");main(update::performClick);waitFor(()->!about.isShowing(),3000);check(((AlertDialog)field(field(a,"appUpdates"),"dialog")).isShowing(),"The About update button opens the update interface");
        return "PASS: "+checks+" player tools assertions on API "+Build.VERSION.SDK_INT+"\n";
    }
    void checkSelection(ListView list,Button select,String screen)throws Exception{
        check(select!=null,"Selection entry is available in "+screen);main(select::performClick);main(()->list.setSelection(list.getHeaderViewsCount()));test.waitForIdleSync();Thread.sleep(300);CheckBox checkbox=find(list,CheckBox.class);check(checkbox!=null&&!checkbox.isChecked(),"Unselected "+screen+" files have empty checkboxes");View card=(View)checkbox.getParent();int height=card.getHeight(),color=((android.graphics.drawable.GradientDrawable)card.getBackground()).getColor().getDefaultColor();int position=list.getFirstVisiblePosition();main(checkbox::performClick);test.waitForIdleSync();Thread.sleep(250);CheckBox selected=find(list,CheckBox.class);View selectedCard=(View)selected.getParent();check(selected.isChecked(),"Checkbox selects the "+screen+" file");check(selectedCard.getHeight()==height&&list.getFirstVisiblePosition()==position&&!textContains(selectedCard,"Выбрано"),"Selecting "+screen+" keeps row height and scroll position");check(((android.graphics.drawable.GradientDrawable)selectedCard.getBackground()).getColor().getDefaultColor()!=color,"Selected "+screen+" row changes its background");shot(screen+"-selection");main(selected::performClick);test.waitForIdleSync();Thread.sleep(150);check(!find(list,CheckBox.class).isChecked(),"Checkbox can deselect the "+screen+" file");
    }
}
